  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
  8→
  9→<div
 10→  id="zcc-widget-{{ block.id }}"
 11→  data-shop="{{ shop.permanent_domain }}"
 12→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 13→  data-block="{{ block.id }}"
 14→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 15→  {{ block.shopify_attributes }}
 16→></div>
 17→
 18→<script>
 19→(function () {
 20→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 21→  var container = document.getElementById(ROOT_ID);
 22→  if (!container) return;
 23→
 24→  var SHOP = container.dataset.shop;
 25→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
 26→
 27→  // Try embedded config from metafield first (instant, no network needed)
 28→  var configStr = container.getAttribute("data-config");
 29→  if (configStr) {
 30→    try {
 31→      renderWidget(JSON.parse(configStr));
 32→      return;
 33→    } catch (e) {
 34→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
 35→    }
 36→  }
 37→
 38→  // Fallback: fetch config from API
 39→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
 40→    .then(function (r) {
 41→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
 42→      return r.json();
 43→    })
 44→    .then(function (cfg) { renderWidget(cfg); })
 45→    .catch(function (err) {
 46→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
 47→      renderWidget({});
 48→    });
 49→
 50→  function renderWidget(cfg) {
 51→    // Merge with defaults
 52→    var D = {
 53→      position: "inline",
 54→      heading: "Check Delivery Availability",
 55→      placeholder: "Enter your zip code",
 56→      buttonText: "Check",
 57→      successMessage: "Great news! We deliver to your area.",
 58→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
 59→      notFoundMessage: "This zip code was not found in our system.",
 60→      primaryColor: "#008060",
 61→      successColor: "#008060",
 62→      errorColor: "#D72C0D",
 63→      backgroundColor: "#FFFFFF",
 64→      textColor: "#202223",
 65→      borderRadius: "8",
 66→      showEta: true,
 67→      showZone: false,
 68→      showWaitlistOnFailure: false,
 69→      customCss: "",
 70→    };
 71→    Object.keys(D).forEach(function (k) {
 72→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
 73→    });
 74→
 75→    var rad = cfg.borderRadius + "px";
 76→    var WID = "zcc-" + ROOT_ID;
 77→
 78→    if (cfg.position === "floating") {
 79→      renderFloating(cfg, WID, rad);
 80→    } else if (cfg.position === "popup") {
 81→      renderPopup(cfg, WID, rad);
 82→    } else {
 83→      renderInline(cfg, WID, rad);
 84→    }
 85→  }
 86→
 87→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
 88→  function injectCss(wid, cfg, rad) {
 89→    var css =
 90→      "#" + wid + "{" +
 91→        "background:" + cfg.backgroundColor + " !important;" +
 92→        "color:" + cfg.textColor + " !important;" +
 93→        "border-radius:" + rad + " !important;" +
 94→        "padding:24px !important;" +
 95→        "border:1px solid #e1e3e5 !important;" +
 96→        "max-width:480px;" +
 97→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
 98→        "box-sizing:border-box !important;" +
 99→      "}" +
100→      "#" + wid + " *{box-sizing:border-box !important}" +
101→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
102→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
103→      "#" + wid + " .zcc-input{" +
104→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
105→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
106→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
107→      "}" +
108→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
109→      "#" + wid + " .zcc-btn{" +
110→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
111→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
112→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
113→      "}" +
114→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
115→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
116→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
117→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
118→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
119→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
120→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
121→      "#" + wid + " .zcc-wl-input{" +
122→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
123→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
124→      "}" +
125→      "#" + wid + " .zcc-wl-btn{" +
126→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
127→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
128→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
129→      "}" +
130→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
131→      (cfg.customCss || "");
132→
133→    var styleEl = document.createElement("style");
134→    styleEl.textContent = css;
135→    document.head.appendChild(styleEl);
136→  }
