252→  // ── Inline position ─────────────────────────────────────────────────────────
253→  function renderInline(cfg, WID, rad) {
254→    injectCss(WID, cfg, rad);
255→    container.id = WID;
256→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
257→    wireWidget(WID, cfg, API_BASE, SHOP);
258→  }
259→
260→  // ── Floating position ────────────────────────────────────────────────────────
261→  function renderFloating(cfg, WID, rad) {
262→    // The original container becomes invisible (just an anchor)
263→    container.style.display = "none";
264→
265→    injectCss(WID, cfg, rad);
266→
267→    // Additional styles for floating UI
268→    var floatCss =
269→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
270→      "#" + WID + "-panel{" +
271→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
272→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
273→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
274→      "}" +
275→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
276→      "#" + WID + "-panel .zcc-panel-header{" +
277→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
278→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
279→      "}" +
280→      "#" + WID + "-panel .zcc-panel-close{" +
281→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
282→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
283→      "}" +
284→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
285→      "#" + WID + "-trigger{" +
286→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
287→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
288→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
289→      "}" +
290→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
291→
292→    var floatStyle = document.createElement("style");
293→    floatStyle.textContent = floatCss;
294→    document.head.appendChild(floatStyle);
295→
296→    // Build floating shell
297→    var floatEl = document.createElement("div");
298→    floatEl.id = WID + "-float";
299→    floatEl.innerHTML =
300→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
301→        '<div class="zcc-panel-header">' +
302→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
303→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
304→        '</div>' +
305→        '<div id="' + WID + '">' +
306→          buildWidgetInner(WID, cfg, cfg.buttonText) +
307→        '</div>' +
308→      '</div>' +
309→      '<button id="' + WID + '-trigger" type="button">' +
310→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
311→        esc(cfg.buttonText || "Check Delivery") +
312→      '</button>';
313→
314→    document.body.appendChild(floatEl);
315→
316→    // Wire toggle
317→    var trigger = document.getElementById(WID + "-trigger");
318→    var panel = document.getElementById(WID + "-panel");
319→    var closeBtn = document.getElementById(WID + "-close");
320→
321→    if (trigger && panel) {
322→      trigger.addEventListener("click", function () {
323→        panel.classList.toggle("zcc-hidden");
324→      });
325→    }
326→    if (closeBtn && panel) {
327→      closeBtn.addEventListener("click", function () {
328→        panel.classList.add("zcc-hidden");
329→      });
330→    }
331→    // Close on outside click
332→    document.addEventListener("click", function (e) {
333→      if (!floatEl.contains(e.target)) {
334→        if (panel) panel.classList.add("zcc-hidden");
335→      }
336→    });
337→
338→    wireWidget(WID, cfg, API_BASE, SHOP);
339→  }
