341→  // ── Popup position ───────────────────────────────────────────────────────────
342→  function renderPopup(cfg, WID, rad) {
343→    injectCss(WID, cfg, rad);
344→
345→    var popupCss =
346→      "#" + WID + "-overlay{" +
347→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
348→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
349→      "}" +
350→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
351→      "#" + WID + "-modal{" +
352→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
353→        "max-width:480px !important;width:100% !important;position:relative !important;" +
354→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
355→      "}" +
356→      "#" + WID + "-modal .zcc-modal-close{" +
357→        "position:absolute !important;top:10px !important;right:14px !important;background:none !important;border:none !important;" +
358→        "font-size:22px !important;line-height:1 !important;cursor:pointer !important;color:" + cfg.textColor + " !important;opacity:.5" +
359→      "}" +
360→      "#" + WID + "-modal .zcc-modal-close:hover{opacity:1 !important}" +
361→      "#" + WID + "-popup-trigger{" +
362→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
363→        "border-radius:" + rad + " !important;padding:10px 24px !important;font-size:14px !important;font-weight:600 !important;" +
364→        "cursor:pointer !important" +
365→      "}" +
366→      "#" + WID + "-popup-trigger:hover{opacity:.9 !important}";
367→
368→    var popupStyle = document.createElement("style");
369→    popupStyle.textContent = popupCss;
370→    document.head.appendChild(popupStyle);
371→
372→    // Trigger button renders in-place (inside the block)
373→    container.innerHTML =
374→      '<button id="' + WID + '-popup-trigger" type="button">' +
375→        esc(cfg.heading) +
376→      '</button>';
377→
378→    // Overlay + modal append to body
379→    var overlay = document.createElement("div");
380→    overlay.id = WID + "-overlay";
381→    overlay.innerHTML =
382→      '<div id="' + WID + '-modal">' +
383→        '<button class="zcc-modal-close" id="' + WID + '-modal-close" type="button" aria-label="Close">&times;</button>' +
384→        '<div id="' + WID + '">' +
385→          buildWidgetInner(WID, cfg, cfg.buttonText) +
386→        '</div>' +
387→      '</div>';
388→    document.body.appendChild(overlay);
389→
390→    var trigger = document.getElementById(WID + "-popup-trigger");
391→    var closeBtn = document.getElementById(WID + "-modal-close");
392→    var modal = document.getElementById(WID + "-modal");
393→
394→    function openPopup() { overlay.classList.add("zcc-open"); }
395→    function closePopup() { overlay.classList.remove("zcc-open"); }
396→
397→    if (trigger) trigger.addEventListener("click", openPopup);
398→    if (closeBtn) closeBtn.addEventListener("click", closePopup);
399→
400→    // Close on overlay backdrop click (not modal content)
401→    overlay.addEventListener("click", function (e) {
402→      if (e.target === overlay) closePopup();
403→    });
404→
405→    // Close on Escape key
406→    document.addEventListener("keydown", function (e) {
407→      if (e.key === "Escape") closePopup();
408→    });
409→
410→    wireWidget(WID, cfg, API_BASE, SHOP);
411→  }
412→
413→  function esc(str) {
414→    return String(str)
415→      .replace(/&/g, "&amp;")
416→      .replace(/</g, "&lt;")
417→      .replace(/>/g, "&gt;")
418→      .replace(/"/g, "&quot;");
419→  }
420→
421→  function escAttr(str) {
422→    return String(str).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
423→  }
424→})();
425→</script>
