 1→import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
 2→import { Outlet, useLoaderData, useRouteError } from "react-router";
 3→import { boundary } from "@shopify/shopify-app-react-router/server";
 4→import { AppProvider } from "@shopify/shopify-app-react-router/react";
 5→import { AppProvider as PolarisAppProvider } from "@shopify/polaris";
 6→import "@shopify/polaris/build/esm/styles.css";
 7→import enTranslations from "@shopify/polaris/locales/en.json";
 8→
 9→import { authenticate } from "../shopify.server";
10→
11→export const loader = async ({ request }: LoaderFunctionArgs) => {
12→  await authenticate.admin(request);
13→
14→  // eslint-disable-next-line no-undef
15→  return { apiKey: process.env.SHOPIFY_API_KEY || "" };
16→};
17→
18→export default function App() {
19→  const { apiKey } = useLoaderData<typeof loader>();
20→
21→  return (
22→    <AppProvider embedded apiKey={apiKey}>
23→      <PolarisAppProvider i18n={enTranslations}>
24→        <s-app-nav>
25→          <s-link href="/app">Dashboard</s-link>
26→          <s-link href="/app/zip-codes">Zip Codes</s-link>
27→          <s-link href="/app/delivery-rules">Delivery Rules</s-link>
28→          <s-link href="/app/waitlist">Waitlist</s-link>
29→          <s-link href="/app/widget">Widget</s-link>
30→          <s-link href="/app/settings">Settings</s-link>
31→        </s-app-nav>
32→        <Outlet />
33→      </PolarisAppProvider>
34→    </AppProvider>
35→  );
36→}
